func (shipmentWhere[Q]) AliasedAs(alias string) shipmentWhere[Q] {
	return buildShipmentWhere[Q](buildShipmentColumns(alias))
}

func buildShipmentWhere[Q psql.Filterable](cols shipmentColumns) shipmentWhere[Q] {
	return shipmentWhere[Q]{
		cols:           cols,
		ID:             psql.Where[Q, string](cols.ID.Expression),
		OrganizationID: psql.Where[Q, string](cols.OrganizationID.Expression),
		BusinessUnitID: psql.Where[Q, string](cols.BusinessUnitID.Expression),
		CustomerID:     psql.Where[Q, string](cols.CustomerID.Expression),
		BillToID:       psql.WhereNull[Q, string](cols.BillToID.Expression),
		ProNumber:      psql.Where[Q, string](cols.ProNumber.Expression),
		Status:         psql.Where[Q, enums.ShipmentStatus](cols.Status.Expression),
		Priority:       psql.Where[Q, int16](cols.Priority.Expression),
		Weight:         psql.WhereNull[Q, int64](cols.Weight.Expression),
		Total:          psql.Where[Q, decimal.Decimal](cols.Total.Expression),
		Hazmat:         psql.Where[Q, bool](cols.Hazmat.Expression),
		Labels:         psql.Where[Q, pq.StringArray](cols.Labels.Expression),
		Attributes:     psql.Where[Q, benchjson.Map](cols.Attributes.Expression),
		StageRank:      psql.Where[Q, int16](cols.StageRank.Expression),
		CanceledAt:     psql.WhereNull[Q, int64](cols.CanceledAt.Expression),
		Version:        psql.Where[Q, int64](cols.Version.Expression),
		CreatedAt:      psql.Where[Q, int64](cols.CreatedAt.Expression),
		UpdatedAt:      psql.Where[Q, int64](cols.UpdatedAt.Expression),
		R:              shipmentWhereR[Q]{cols: cols},
	}
}

// shipmentWhereR holds the relationship-based filters of
// shipmentWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type shipmentWhereR[Q psql.Filterable] struct {
	cols shipmentColumns
}

// HasMoves filters parents that have a matching Moves using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Moves).
func (w shipmentWhereR[Q]) HasMoves(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Moves.NameExpr()),
		sm.Where(Moves.Columns.ShipmentID.EQ(w.cols.ID)),
		sm.Where(Moves.Columns.OrganizationID.EQ(w.cols.OrganizationID)),
		sm.Where(Moves.Columns.BusinessUnitID.EQ(w.cols.BusinessUnitID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasCustomer filters parents that have a matching Customer using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Customers).
func (w shipmentWhereR[Q]) HasCustomer(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Customers.NameExpr()),
		sm.Where(Customers.Columns.ID.EQ(w.cols.CustomerID)),
		sm.Where(Customers.Columns.OrganizationID.EQ(w.cols.OrganizationID)),
		sm.Where(Customers.Columns.BusinessUnitID.EQ(w.cols.BusinessUnitID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// NULL-tolerant scan buffer for shipmentScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type shipmentPreloadBuf struct {
	ID             null.Val[string]
	OrganizationID null.Val[string]
	BusinessUnitID null.Val[string]
	CustomerID     null.Val[string]
	BillToID       null.Val[string]
	ProNumber      null.Val[string]
	Status         null.Val[enums.ShipmentStatus]
	Priority       null.Val[int16]
	Weight         null.Val[int64]
	Total          null.Val[decimal.Decimal]
	Hazmat         null.Val[bool]
	Labels         null.Val[pq.StringArray]
	Attributes     null.Val[benchjson.Map]
	StageRank      null.Val[int16]
	CanceledAt     null.Val[int64]
	Version        null.Val[int64]
	CreatedAt      null.Val[int64]
	UpdatedAt      null.Val[int64]
}

// shipmentScanMapperNullable maps the preloaded shipment
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func shipmentScanMapperNullable(prefix string) scan.Mapper[*Shipment] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Shipment, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *shipmentPreloadBuf) any
		}
		targets := make([]target, 0, 18)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.ID }})
			case "organization_id":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.OrganizationID }})
			case "business_unit_id":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.BusinessUnitID }})
			case "customer_id":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.CustomerID }})
			case "bill_to_id":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.BillToID }})
			case "pro_number":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.ProNumber }})
			case "status":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.Status }})
			case "priority":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.Priority }})
			case "weight":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.Weight }})
			case "total":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.Total }})
			case "hazmat":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.Hazmat }})
			case "labels":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.Labels }})
			case "attributes":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.Attributes }})
			case "stage_rank":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.StageRank }})
			case "canceled_at":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.CanceledAt }})
			case "version":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.Version }})
			case "created_at":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *shipmentPreloadBuf) any { return &b.UpdatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(shipmentPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Shipment, error) {
				buf := link.(*shipmentPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.OrganizationID.IsValue()) &&
					!(buf.BusinessUnitID.IsValue()) &&
					!(buf.CustomerID.IsValue()) &&
					!(buf.BillToID.IsValue()) &&
					!(buf.ProNumber.IsValue()) &&
					!(buf.Status.IsValue()) &&
					!(buf.Priority.IsValue()) &&
					!(buf.Weight.IsValue()) &&
					!(buf.Total.IsValue()) &&
					!(buf.Hazmat.IsValue()) &&
					!(buf.Labels.IsValue()) &&
					!(buf.Attributes.IsValue()) &&
					!(buf.StageRank.IsValue()) &&
					!(buf.CanceledAt.IsValue()) &&
					!(buf.Version.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.UpdatedAt.IsValue()) {
					return nil, nil
				}

				o := new(Shipment)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.OrganizationID.IsValue() {
					o.OrganizationID = buf.OrganizationID.MustGet()
				}
				if buf.BusinessUnitID.IsValue() {
					o.BusinessUnitID = buf.BusinessUnitID.MustGet()
				}
				if buf.CustomerID.IsValue() {
					o.CustomerID = buf.CustomerID.MustGet()
				}
				o.BillToID = buf.BillToID
				if buf.ProNumber.IsValue() {
					o.ProNumber = buf.ProNumber.MustGet()
				}
				if buf.Status.IsValue() {
					o.Status = buf.Status.MustGet()
				}
				if buf.Priority.IsValue() {
					o.Priority = buf.Priority.MustGet()
				}
				o.Weight = buf.Weight
				if buf.Total.IsValue() {
					o.Total = buf.Total.MustGet()
				}
				if buf.Hazmat.IsValue() {
					o.Hazmat = buf.Hazmat.MustGet()
				}
				if buf.Labels.IsValue() {
					o.Labels = buf.Labels.MustGet()
				}
				if buf.Attributes.IsValue() {
					o.Attributes = buf.Attributes.MustGet()
				}
				if buf.StageRank.IsValue() {
					o.StageRank = buf.StageRank.MustGet()
				}
				o.CanceledAt = buf.CanceledAt
				if buf.Version.IsValue() {
					o.Version = buf.Version.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.UpdatedAt.IsValue() {
					o.UpdatedAt = buf.UpdatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Shipment) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Moves":
		rels, ok := retrieved.(MoveSlice)
		if !ok {
			return fmt.Errorf("shipment cannot load %T as %q", retrieved, name)
		}

		o.R.Moves = rels
		o.R.Loaded.Moves = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Shipment = o
				rel.R.Loaded.Shipment = true
			}
		}
		return nil
	case "Customer":
		rel, ok := retrieved.(*Customer)
		if !ok {
			return fmt.Errorf("shipment cannot load %T as %q", retrieved, name)
		}

		o.R.Customer = rel
		o.R.Loaded.Customer = true

		if rel != nil {
			rel.R.Shipments = ShipmentSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("shipment has no relationship %q", name)
	}
}

type shipmentPreloader struct {
	Customer func(...psql.PreloadOption) psql.Preloader
}

func buildShipmentPreloader() shipmentPreloader {
	return shipmentPreloader{
		Customer: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Customer, CustomerSlice](psql.PreloadRel{
				Name: "Customer",
				Sides: []psql.PreloadSide{
					{
						From:        Shipments,
						To:          Customers,
						FromColumns: []string{"customer_id", "organization_id", "business_unit_id"},
						ToColumns:   []string{"id", "organization_id", "business_unit_id"},
					},
				},
			}, Customers.Columns.Names(), customerScanMapperNullable, opts...)
		},
	}
}

type shipmentThenLoader[Q orm.Loadable] struct {
	Moves    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Customer func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildShipmentThenLoader[Q orm.Loadable]() shipmentThenLoader[Q] {
	type MovesLoadInterface interface {
		LoadMoves(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type CustomerLoadInterface interface {
		LoadCustomer(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return shipmentThenLoader[Q]{
		Moves: thenLoadBuilder[Q](
			"Moves",
			func(ctx context.Context, exec bob.Executor, retrieved MovesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadMoves(ctx, exec, mods...)
			},
		),
		Customer: thenLoadBuilder[Q](
			"Customer",
			func(ctx context.Context, exec bob.Executor, retrieved CustomerLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCustomer(ctx, exec, mods...)
			},
		),
	}
}

// LoadMoves loads the shipment's Moves into the .R struct
func (o *Shipment) LoadMoves(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Moves = nil
	o.R.Loaded.Moves = false

	related, err := o.Moves(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Shipment = o
		rel.R.Loaded.Shipment = true
	}

	o.R.Moves = related
	o.R.Loaded.Moves = true
	return nil
}

// LoadMoves loads the shipment's Moves into the .R struct
func (os ShipmentSlice) LoadMoves(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	moves, err := os.Moves(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Moves = nil
		o.R.Loaded.Moves = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range moves {

			if !(o.ID == rel.ShipmentID) {
				continue
			}

			if !(o.OrganizationID == rel.OrganizationID) {
				continue
			}

			if !(o.BusinessUnitID == rel.BusinessUnitID) {
				continue
			}

			rel.R.Shipment = o
			rel.R.Loaded.Shipment = true

			o.R.Moves = append(o.R.Moves, rel)
		}
	}

	return nil
}

// LoadCustomer loads the shipment's Customer into the .R struct
func (o *Shipment) LoadCustomer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Customer = nil
	o.R.Loaded.Customer = false

	related, err := o.Customer(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.Shipments = ShipmentSlice{o}

	o.R.Customer = related
	o.R.Loaded.Customer = true
	return nil
}

// LoadCustomer loads the shipment's Customer into the .R struct
func (os ShipmentSlice) LoadCustomer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	customers, err := os.Customer(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Customer = nil
		o.R.Loaded.Customer = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range customers {

			if !(o.CustomerID == rel.ID) {
				continue
			}

			if !(o.OrganizationID == rel.OrganizationID) {
				continue
			}

			if !(o.BusinessUnitID == rel.BusinessUnitID) {
				continue
			}

			rel.R.Shipments = append(rel.R.Shipments, o)

			o.R.Customer = rel
			break
		}
	}

	return nil
}

// shipmentC is where relationship counts are stored.
type shipmentC struct {
	Moves *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Shipment) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Moves":
		o.C.Moves = &count
	}
	return nil
}

type shipmentCountPreloader struct {
	Moves func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildShipmentCountPreloader() shipmentCountPreloader {
	return shipmentCountPreloader{
		Moves: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Shipment]("Moves", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Shipments.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Moves.NameAsExpr()),
					sm.Where(psql.Quote(Moves.Alias(), "shipment_id").EQ(psql.Quote(parent, "id"))),
					sm.Where(psql.Quote(Moves.Alias(), "organization_id").EQ(psql.Quote(parent, "organization_id"))),
					sm.Where(psql.Quote(Moves.Alias(), "business_unit_id").EQ(psql.Quote(parent, "business_unit_id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type shipmentCountThenLoader[Q orm.Loadable] struct {
	Moves func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildShipmentCountThenLoader[Q orm.Loadable]() shipmentCountThenLoader[Q] {
	type MovesCountInterface interface {
		LoadCountMoves(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return shipmentCountThenLoader[Q]{
		Moves: countThenLoadBuilder[Q](
			"Moves",
			func(ctx context.Context, exec bob.Executor, retrieved MovesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountMoves(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountMoves loads the count of Moves into the C struct
func (o *Shipment) LoadCountMoves(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Moves(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Moves = &count
	return nil
}

// LoadCountMoves loads the count of Moves for a slice in a single batch query
func (os ShipmentSlice) LoadCountMoves(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[string], 0, len(os))
	pkOrganizationID := make(pgtypes.Array[string], 0, len(os))
	pkBusinessUnitID := make(pgtypes.Array[string], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
		pkOrganizationID = append(pkOrganizationID, o.OrganizationID)
		pkBusinessUnitID = append(pkBusinessUnitID, o.BusinessUnitID)
	}

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID string

		OrganizationID string

		BusinessUnitID string
		Count          int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			Moves.Columns.ShipmentID.As("id"),
			Moves.Columns.OrganizationID.As("organization_id"),
			Moves.Columns.BusinessUnitID.As("business_unit_id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(Moves.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.InnerJoin(psql.Select(
			sm.Distinct(),
			sm.Columns(
				psql.Quote("bob_rel_keys_src", "ShipmentID"),
				psql.Quote("bob_rel_keys_src", "OrganizationID"),
				psql.Quote("bob_rel_keys_src", "BusinessUnitID"),
			),
			sm.From(psql.F("unnest",
				psql.Cast(psql.Arg(pkID), "text[]"),
				psql.Cast(psql.Arg(pkOrganizationID), "text[]"),
				psql.Cast(psql.Arg(pkBusinessUnitID), "text[]"),
			)).As("bob_rel_keys_src", "ShipmentID", "OrganizationID", "BusinessUnitID"),
		)).As("bob_rel_keys").On(
			Moves.Columns.ShipmentID.EQ(psql.Quote("bob_rel_keys", "ShipmentID")),
			Moves.Columns.OrganizationID.EQ(psql.Quote("bob_rel_keys", "OrganizationID")),
			Moves.Columns.BusinessUnitID.EQ(psql.Quote("bob_rel_keys", "BusinessUnitID")),
		),
		// GROUP BY fk columns
		sm.GroupBy(Moves.Columns.ShipmentID),
		sm.GroupBy(Moves.Columns.OrganizationID),
		sm.GroupBy(Moves.Columns.BusinessUnitID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Composite FK: use a key struct
	type countKey struct {
		ID string

		OrganizationID string

		BusinessUnitID string
	}
	countMap := make(map[countKey]int64, len(results))
	for _, r := range results {
		countMap[countKey{
			ID: r.ID,

			OrganizationID: r.OrganizationID,

			BusinessUnitID: r.BusinessUnitID,
		}] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[countKey{
			ID: o.ID,

			OrganizationID: o.OrganizationID,

			BusinessUnitID: o.BusinessUnitID,
		}]
		o.C.Moves = &count
	}

	return nil
}

type shipmentJoins[Q dialect.Joinable] struct {
	typ      string
	Moves    modAs[Q, moveColumns]
	Customer modAs[Q, customerColumns]
}

func (j shipmentJoins[Q]) aliasedAs(alias string) shipmentJoins[Q] {
	return buildShipmentJoins[Q](buildShipmentColumns(alias), j.typ)
}

func buildShipmentJoins[Q dialect.Joinable](cols shipmentColumns, typ string) shipmentJoins[Q] {
	return shipmentJoins[Q]{
		typ: typ,
		Moves: modAs[Q, moveColumns]{
			c: Moves.Columns,
			f: func(to moveColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Moves.NameExpr().As(to.Alias())).On(
						to.ShipmentID.EQ(cols.ID), to.OrganizationID.EQ(cols.OrganizationID), to.BusinessUnitID.EQ(cols.BusinessUnitID),
					))
				}

				return mods
			},
		},
		Customer: modAs[Q, customerColumns]{
			c: Customers.Columns,
			f: func(to customerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Customers.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CustomerID), to.OrganizationID.EQ(cols.OrganizationID), to.BusinessUnitID.EQ(cols.BusinessUnitID),
					))
				}

				return mods
			},
		},
	}
}
